import {BASE,LIMITS,FEATURES,defaults,validate,rect,normalized,resized,transform,spouseArea,PERFORMANCE_PROFILES,recommendedProfile,profileLimits,formatMultiplier} from './core.mjs';
import {createMapWorker,loadBase,loadImage,whenVisible} from './resources.mjs';
import {MapRenderer,visibleTiles} from './renderer.mjs';
import {download} from './export.mjs';
const $=id=>document.getElementById(id),canvas=$('map'),ctx=canvas.getContext('2d');
let profile='auto',busy=false;
const autoProfile=recommendedProfile(navigator.deviceMemory);
const currentLimits=()=>profileLimits(profile==='auto'?autoProfile:profile);
let config=autoProfile==='high'?defaults(2048,2048):defaults(),selected=FEATURES[0],history=[],ready=false,worker,renderer,images={},zoom=1,offset={x:0,y:0},drag=null,toastTimer,framePending=false;
function toast(message){$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),4500);}
function check(next){if(next.Width*next.Height>currentLimits().area)throw Error('地图超过当前性能档位的面积上限，请提高档位或缩小尺寸。');const errors=validate(next);if(errors.length)throw Error(errors[0]);}
async function prepare(next){check(next);const display=await worker.call('generate',{config:normalized(next)}),result=new MapRenderer(draw);await result.setMap(display);return result;}
async function commit(next,message,{remember=true,fitView=false}={}){
 if(!ready){toast('地图尚未载入，请稍候。');return false;}
 if(busy)return false;
 if(JSON.stringify(normalized(next))===JSON.stringify(config)){if(fitView)fit();return true;}
 return runBusy('正在生成地图…',async()=>{const result=await prepare(next);if(remember){history.push(structuredClone(config));if(history.length>60)history.shift();}config=normalized(next);renderer=result;sync();if(fitView)fit();if(message)toast(message);return true;});
}
function sync(){
 $('width').value=config.Width;$('height').value=config.Height;$('dimensions').textContent=`${config.Width} × ${config.Height}`;$('area').textContent=(config.Width*config.Height).toLocaleString();$('ratio').textContent=`Farm x ${formatMultiplier(config.Width,config.Height)}`;$('undo').disabled=!history.length;
 document.querySelectorAll('[data-size]').forEach(b=>b.classList.toggle('active',b.dataset.size===`${config.Width},${config.Height}`));
 $('feature-list').replaceChildren(...FEATURES.map(f=>{const r=rect(f,config),b=document.createElement('button');b.className='feature'+(f.id===selected.id?' active':'');b.innerHTML=`<span class="feature-icon">${f.icon}</span><span><strong>${f.name}</strong><span class="coord">${config.Positions[f.id].X}, ${config.Positions[f.id].Y} · ${f.w} × ${f.h}</span></span>`;b.onclick=()=>{selected=f;sync();};return b;}));
 const r={x:config.Positions[selected.id].X,y:config.Positions[selected.id].Y};$('selected-name').textContent=selected.name;$('selected-note').textContent=selected.note;$('pos-x').value=r.x;$('pos-y').value=r.y;
 for(const id of ['pos-x','pos-y','move','restore'])$(id).disabled=false;$('pos-x').disabled=selected.edge==='east';$('pos-y').disabled=selected.edge==='south'||selected.edge==='north';
 draw();
}
const loadingBuildings=new Set();
function requestBuilding(name){if(images[name]||loadingBuildings.has(name))return;loadingBuildings.add(name);loadImage(name).then(img=>{images[name]=img;draw();}).catch(()=>toast('建筑预览图片加载失败，请刷新重试。'));}
function renderBuilding(f,r){if(!f.building)return;const name={Greenhouse:'Greenhouse',Farmhouse:'houses','Shipping Bin':'Shipping Bin','Pet Bowl':'Pet Bowl'}[f.id];if((r.x+12)*16*zoom+offset.x<0||r.x*16*zoom+offset.x>canvas.clientWidth||(r.y+12)*16*zoom+offset.y<0||(r.y-5)*16*zoom+offset.y>canvas.clientHeight)return;requestBuilding(name);let img,sx=0,sy=0,sw,sh,dx=r.x*16,dy=r.y*16;if(f.id==='Greenhouse'){img=images.Greenhouse;sw=112;sh=160;sy=160;dy-=64;}else if(f.id==='Farmhouse'){img=images.houses;sw=160;sh=144;dx-=16;dy-=64;}else if(f.id==='Shipping Bin'){img=images['Shipping Bin'];sw=32;sh=32;dy-=16;}else if(f.id==='Pet Bowl'){img=images['Pet Bowl'];sx=32;sw=32;sh=32;}if(img)ctx.drawImage(img,sx,sy,sw,sh,dx,dy,sw,sh);}
function draw(){if(framePending)return;framePending=true;requestAnimationFrame(()=>{framePending=false;renderFrame();});}
function renderFrame(){
 const started=performance.now();
 const dpr=window.devicePixelRatio||1,w=canvas.clientWidth,h=canvas.clientHeight;if(!w||!h)return;if(canvas.width!==Math.round(w*dpr)||canvas.height!==Math.round(h*dpr)){canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr);}ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,w,h);if(!renderer)return;ctx.imageSmoothingEnabled=false;ctx.translate(offset.x,offset.y);ctx.scale(zoom,zoom);const mw=config.Width*16,mh=config.Height*16;
 renderer.draw(ctx,zoom,offset,w,h);
 if($('grid').checked&&zoom>=.3){const v=visibleTiles(config.Width,config.Height,zoom,offset,w,h);ctx.strokeStyle='#283b242c';ctx.lineWidth=.65/zoom;ctx.beginPath();for(let x=v.left*16;x<=v.right*16;x+=16){ctx.moveTo(x,v.top*16);ctx.lineTo(x,v.bottom*16);}for(let y=v.top*16;y<=v.bottom*16;y+=16){ctx.moveTo(v.left*16,y);ctx.lineTo(v.right*16,y);}ctx.stroke();}
 const placedLabels=[]; const fs=[...FEATURES].sort((a,b)=>rect(a,config).y-rect(b,config).y);for(const f of fs){let r=rect(f,config);if(drag?.feature?.id===f.id&&drag.preview)r={...r,...drag.preview};if(drag?.feature?.id===f.id&&drag.ghost){ctx.globalAlpha=.65;ctx.drawImage(drag.ghost,r.x*16,r.y*16);ctx.globalAlpha=1;}renderBuilding(f,r);if(f===selected){ctx.fillStyle='#b6d68233';ctx.fillRect(r.x*16,r.y*16,r.w*16,r.h*16);ctx.strokeStyle=drag?.invalid?'#e78669':'#f1f4b8';ctx.lineWidth=2/zoom;ctx.strokeRect(r.x*16,r.y*16,r.w*16,r.h*16);if(f.id==='Farmhouse'){const a=spouseArea(config);ctx.setLineDash([4/zoom,4/zoom]);ctx.strokeStyle='#eebf72';ctx.strokeRect(a.x*16,a.y*16,a.w*16,a.h*16);ctx.setLineDash([]);}}if($('labels').checked){const x=(r.x+r.w/2)*16,y=(r.y+r.h)*16;ctx.save();ctx.translate(x,y);ctx.scale(1/zoom,1/zoom);ctx.font='12px system-ui';const tw=ctx.measureText(f.name).width;ctx.fillStyle=f===selected?'#f4f3d7':'#1c392eea';let ly=5;const lx=x*zoom-tw/2-9,lw=tw+18;while(placedLabels.some(b=>lx<b.x+b.w&&lx+lw>b.x&&y*zoom+ly<b.y+27&&y*zoom+ly+27>b.y))ly+=28;placedLabels.push({x:lx,y:y*zoom+ly,w:lw});if(ly>5){ctx.strokeStyle='#e4e8cf99';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(0,0);ctx.lineTo(0,ly);ctx.stroke();}ctx.beginPath();ctx.roundRect(-tw/2-9,ly,tw+18,25,4);ctx.fill();ctx.fillStyle=f===selected?'#29492d':'#eaf0d7';ctx.textAlign='center';ctx.fillText(f.name,0,ly+17);ctx.restore();}}
 canvas.dataset.renderMs=(performance.now()-started).toFixed(2);canvas.dataset.cacheBytes=renderer.bytes;canvas.dataset.chunksBuilt=renderer.stats.chunksBuilt;
 $('zoom-value').textContent=(zoom<.1?(zoom*100).toFixed(1):Math.round(zoom*100))+'%';
}
function fitZoom(){return Math.min((canvas.clientWidth-48)/(config.Width*16),(canvas.clientHeight-48)/(config.Height*16));}
function fit(){zoom=fitZoom();offset={x:(canvas.clientWidth-config.Width*16*zoom)/2,y:(canvas.clientHeight-config.Height*16*zoom)/2-10};draw();}
function scale(factor,x=canvas.clientWidth/2,y=canvas.clientHeight/2){const n=Math.max(Math.min(.08,fitZoom()/2),Math.min(3,zoom*factor));offset={x:x-(x-offset.x)*n/zoom,y:y-(y-offset.y)*n/zoom};zoom=n;draw();}
function point(e){const r=canvas.getBoundingClientRect();return {x:(e.clientX-r.left-offset.x)/zoom/16,y:(e.clientY-r.top-offset.y)/zoom/16};}
canvas.addEventListener('pointerdown',e=>{if(!ready||busy)return;const p=point(e),f=[...FEATURES].reverse().find(f=>{const r=rect(f,config);return p.x>=r.x&&p.x<r.x+r.w&&p.y>=r.y-2&&p.y<r.y+r.h;});if(f){selected=f;sync();if(f.movable){const r=rect(f,config);drag={feature:f,delta:{x:p.x-r.x,y:p.y-r.y},preview:{x:r.x,y:r.y},ghost:f.stamp?renderer.capture(r):null};}else toast(`${f.name}受保护，不能移动或删除。`);}else drag={start:{x:e.clientX,y:e.clientY},offset:{...offset}};canvas.setPointerCapture(e.pointerId);});
canvas.addEventListener('pointermove',e=>{const p=point(e);$('coordinates').textContent=`X ${Math.floor(p.x)} · Y ${Math.floor(p.y)}  / 地图坐标`;if(drag?.feature){drag.preview={x:Math.round(p.x-drag.delta.x),y:Math.round(p.y-drag.delta.y)};if(drag.feature.edge==='east')drag.preview.x=config.Width-1+drag.feature.ox;if(drag.feature.edge==='south')drag.preview.y=config.Height-1+drag.feature.oy;if(drag.feature.edge==='north')drag.preview.y=0;const c=structuredClone(config);c.Positions[drag.feature.id]={X:drag.preview.x-(drag.feature.ox||0),Y:drag.preview.y-(drag.feature.oy||0)};drag.invalid=validate(c).length>0;draw();}else if(drag){offset={x:drag.offset.x+e.clientX-drag.start.x,y:drag.offset.y+e.clientY-drag.start.y};draw();}});
canvas.addEventListener('pointerup',()=>{if(drag?.feature){const c=structuredClone(config);c.Positions[drag.feature.id]={X:drag.preview.x-(drag.feature.ox||0),Y:drag.preview.y-(drag.feature.oy||0)};commit(c);}drag=null;draw();});canvas.addEventListener('pointercancel',()=>{drag=null;draw();});canvas.addEventListener('wheel',e=>{e.preventDefault();const r=canvas.getBoundingClientRect();scale(e.deltaY<0?1.12:1/1.12,e.clientX-r.left,e.clientY-r.top);},{passive:false});
function move(x,y){const c=structuredClone(config);c.Positions[selected.id]={X:x,Y:y};return commit(c,'设施组及关联坐标已更新，通行检查通过。');}
$('move').onclick=()=>move(Number($('pos-x').value),Number($('pos-y').value));$('restore').onclick=()=>{const p=transform(selected.x,selected.y,config);move(p.X,p.Y);};$('resize').onclick=()=>{const c=resized(config,Number($('width').value),Number($('height').value));commit(c,'地图尺寸已更新。',{fitView:true});};
document.querySelectorAll('[data-size]').forEach(b=>b.onclick=()=>{const [Width,Height]=b.dataset.size.split(',').map(Number);commit(resized(config,Width,Height),null,{fitView:true});});
$('undo').onclick=async()=>{if(!busy&&history.length){const previous=history.at(-1);if(await commit(previous,null,{remember:false,fitView:true})){history.pop();sync();}}};$('fit').onclick=fit;$('zoom-in').onclick=()=>scale(1.3);$('zoom-out').onclick=()=>scale(1/1.3);$('grid').onchange=draw;$('labels').onchange=draw;
$('export-tmx').onclick=()=>runBusy('正在导出 TMX…',async()=>{if(!ready)throw Error('地图尚未载入');const blob=await worker.call('export',{config:normalized(config)});download('Farm.tmx',blob,'application/xml');toast('Farm.tmx 已导出。');});
$('help').onclick=()=>$('help-dialog').showModal();$('close-help').onclick=()=>$('help-dialog').close();$('help-dialog').onclick=e=>{if(e.target===$('help-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}};
window.addEventListener('keydown',e=>{if(e.key==='Escape'){drag=null;draw();}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)){e.preventDefault();$('undo').click();}});
function updatePerformance(){const limits=currentLimits(),selected=profile==='auto'?autoProfile:profile;$('width').max=limits.width;$('height').max=limits.height;$('size-limit').textContent=`最小 ${BASE.width} × ${BASE.height} · 当前最多 ${limits.area.toLocaleString()} 格`;$('performance-note').textContent=profile==='auto'?(Number.isFinite(navigator.deviceMemory)?`按浏览器提供的内存信息推荐：${PERFORMANCE_PROFILES[selected].label}。可手动切换。`:'浏览器未提供内存信息，默认轻量档。可按电脑性能手动切换。'):`${PERFORMANCE_PROFILES[selected].label}档 · 较大地图需要更多内存与生成时间。`;}
$('performance').onchange=()=>{const next=$('performance').value,limits=profileLimits(next==='auto'?autoProfile:next);if(config.Width*config.Height>limits.area){$('performance').value=profile;toast('请先缩小当前地图，再降低性能档位。');return;}profile=next;updatePerformance();};
async function runBusy(message,fn){if(busy)return;busy=true;const overlay=document.createElement('div');overlay.className='busy-overlay';overlay.textContent=message;overlay.setAttribute('role','status');document.body.append(overlay);try{await new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));return await fn();}catch(e){toast(e.message);return false;}finally{overlay.remove();busy=false;}}
updatePerformance();
new ResizeObserver(()=>fit()).observe($('map-viewport'));
try{
 await whenVisible($('map-viewport'));worker=createMapWorker();await worker.call('init',{base:await loadBase()});renderer=await prepare(config);ready=true;$('loading').remove();sync();fit();
}catch(e){$('loading').textContent='地图加载失败，请刷新页面重试。';console.error(e);}

if(document.modelContext?.registerTool){for(const tool of [{name:'read_farm_plan',description:'读取当前农场尺寸和点位。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>normalized(config)},{name:'configure_farm_plan',description:'在编辑器中校验并更新农场规划；不会写入游戏或下载文件。',inputSchema:{type:'object',properties:{Width:{type:'integer'},Height:{type:'integer'},Positions:{type:'object'}},required:['Width','Height','Positions'],additionalProperties:false},execute:async input=>{if(!ready||busy)throw Error('地图尚未载入或正在计算');const c={...input,SchemaVersion:2};check(c);if(!await commit(c,null,{fitView:true}))throw Error('地图规划未通过检查');return normalized(config);}}])try{Promise.resolve(document.modelContext.registerTool(tool)).catch(console.error);}catch(e){console.error(e);}}
